//! Layer 1 UI -> Tcl Contract Suite: verifies every Tcl command template
//! generated by the InFormal React workbench (`App.tsx`, `workbenchController.ts`,
//! `FormalApps/*`) against a real `informal_fpv::Shell` in both JasperGold (`jg`)
//! and VC Formal (`vcf`) flavors so `ui/src/mock.ts` can never mask syntax drift.

use informal_engine::Effort;
use informal_fpv::{Flavor, Orchestration, Session, Shell};
use std::path::{Path, PathBuf};
use std::time::Duration;

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn make_shell(flavor: Flavor, tag: &str) -> Option<Shell> {
    let engines = informal_bmc::engines();
    if engines.is_empty() {
        informal_engine::tool_missing("needs in-house engines");
        return None;
    }
    let work = std::env::temp_dir().join(format!(
        "informal-ui-tcl-contract-{tag}-{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&work);
    Some(Shell::new(Session::new(engines, work), flavor))
}

#[test]
fn ui_jg_commands_execute_cleanly_on_real_shell() {
    let Some(sh) = make_shell(Flavor::Jg, "jg") else {
        return;
    };
    let rtl = root().join("tests/fpv/counter/counter.sv");
    sh.eval(&format!(
        "analyze -sv12 {{{}}}; elaborate -top counter; clock clk; reset -expression {{!rst_n}}",
        rtl.display()
    ))
    .unwrap();
    sh.eval("assert -name a_max {q <= 4'd9}").unwrap();
    sh.eval("assert -name a_never9 {q != 4'd9}").unwrap();
    sh.eval("cover -name c_done {$rose(done)}").unwrap();
    sh.eval("assume -name m_en {en |=> en}").unwrap();

    // Effort & budget popover commands (App.tsx)
    for (tok, expected) in [
        ("low", Effort::Low),
        ("standard", Effort::Standard),
        ("high", Effort::High),
        ("max", Effort::Max),
    ] {
        sh.eval(&format!("set_prove_effort {tok}")).unwrap();
        assert_eq!(sh.session.borrow().effort, expected);
    }
    assert_eq!(sh.eval("set_prove_effort").unwrap(), "max");
    sh.eval("set_prove_effort standard").unwrap();

    sh.eval("set_prove_time_limit 5m").unwrap();
    assert_eq!(sh.session.borrow().time_limit, Duration::from_secs(300));
    sh.eval("set_prove_per_property_time_limit 30s").unwrap();
    assert_eq!(sh.session.borrow().time_limit, Duration::from_secs(30));

    sh.eval("set_prove_total_time_limit 2m").unwrap();
    assert_eq!(
        sh.session.borrow().total_time_limit,
        Some(Duration::from_secs(120))
    );
    sh.eval("set_prove_total_time_limit off").unwrap();
    assert_eq!(sh.session.borrow().total_time_limit, None);

    sh.eval("set_max_trace_length 50").unwrap();
    assert_eq!(sh.session.borrow().max_trace_length, Some(50));
    sh.eval("set_max_trace_length off").unwrap();
    assert_eq!(sh.session.borrow().max_trace_length, None);

    for (tok, expected) in [
        ("on", Orchestration::On),
        ("off", Orchestration::Off),
        ("auto", Orchestration::Auto),
    ] {
        sh.eval(&format!("set_prove_orchestration {tok}")).unwrap();
        assert_eq!(sh.session.borrow().orchestration, expected);
    }

    // UX-9 propertyToggleCmd (JG): `<kind> -disable/-enable {<name>}`
    sh.eval("assert -disable {a_max}").unwrap();
    assert!(
        !sh.session
            .borrow()
            .props
            .iter()
            .find(|p| p.name == "a_max")
            .unwrap()
            .enabled
    );
    sh.eval("assert -enable {a_max}").unwrap();
    assert!(
        sh.session
            .borrow()
            .props
            .iter()
            .find(|p| p.name == "a_max")
            .unwrap()
            .enabled
    );

    sh.eval("assume -disable {m_en}").unwrap();
    assert!(
        !sh.session
            .borrow()
            .props
            .iter()
            .find(|p| p.name == "m_en")
            .unwrap()
            .enabled
    );
    sh.eval("assume -enable {m_en}").unwrap();

    sh.eval("cover -disable {c_done}").unwrap();
    sh.eval("cover -enable {c_done}").unwrap();

    // UX-9 signalStopatCmd (JG): `stopat <rel>` / `stopat -clear <rel>`
    sh.eval("stopat q").unwrap();
    assert_eq!(sh.session.borrow().stopats_of("<embedded>"), ["q"]);
    sh.eval("stopat -clear q").unwrap();
    assert!(sh.session.borrow().stopats_of("<embedded>").is_empty());

    // UX-7 Environment pill context menu commands
    let _ = sh.eval("check_assumptions -conflict").unwrap();
    assert_eq!(sh.eval("check_assumptions -dead_end").unwrap(), "alive");
    assert_eq!(sh.eval("check_assumptions -live").unwrap(), "none");
    assert_eq!(sh.eval("check_assumptions -live -conflict").unwrap(), "");

    // Single-property & full-task prove + why_cex
    sh.eval("prove -property a_never9").unwrap();
    let why_json = sh.eval("why_cex -property a_never9 -json").unwrap();
    assert!(why_json.contains("\"failure_frame\""), "{why_json}");

    // FormalApps UI commands (Cov, X-Prop, SPV)
    sh.eval("check_cov -init -model {coi branch}").unwrap();
    sh.eval("check_cov -measure").unwrap();
    sh.eval("check_xprop -init").unwrap();
    sh.eval("check_spv -create -from en -to done").unwrap();
    sh.eval("check_spv -clear").unwrap();

    let work = sh.session.borrow().workdir.clone();
    let _ = std::fs::remove_dir_all(work);
}

#[test]
fn ui_vcf_commands_execute_cleanly_on_real_shell() {
    let Some(sh) = make_shell(Flavor::Vcf, "vcf") else {
        return;
    };
    let rtl = root().join("tests/fpv/counter/counter.sv");
    sh.eval(&format!(
        "read_file -top counter -format sverilog -vcs {{{}}}; create_clock clk -period 10; create_reset rst_n -sense low",
        rtl.display()
    ))
    .unwrap();
    sh.eval("fvassert p_max -expr {q <= 4'd9}").unwrap();

    // VCF budget & effort commands emitted by App.tsx when flavor === "vcf"
    sh.eval("set_fml_var fml_effort high").unwrap();
    assert_eq!(sh.session.borrow().effort, Effort::High);
    sh.eval("set_fml_var fml_max_time 45s").unwrap();
    assert_eq!(sh.session.borrow().time_limit, Duration::from_secs(45));
    sh.eval("set_fml_var fml_max_depth 30").unwrap();
    assert_eq!(sh.session.borrow().max_trace_length, Some(30));
    sh.eval("set_fml_var fml_max_depth off").unwrap();
    assert_eq!(sh.session.borrow().max_trace_length, None);

    // VCF property toggle & signal snip_driver commands
    sh.eval("fvdisable {p_max}").unwrap();
    assert!(
        !sh.session
            .borrow()
            .props
            .iter()
            .find(|p| p.name == "p_max")
            .unwrap()
            .enabled
    );
    sh.eval("fvenable {p_max}").unwrap();

    sh.eval("snip_driver q").unwrap();
    assert_eq!(sh.session.borrow().stopats_of("<embedded>"), ["q"]);
    sh.eval("snip_driver -clear q").unwrap();
    assert!(sh.session.borrow().stopats_of("<embedded>").is_empty());

    assert_eq!(sh.eval("check_assumptions -live").unwrap(), "none");
    sh.eval("check_fv -property {p_max}").unwrap();

    let work = sh.session.borrow().workdir.clone();
    let _ = std::fs::remove_dir_all(work);
}
